SELECT 
  s.STORE_ID,
  s.ADDRESS,
  COUNT(CASE WHEN p.IS_LEADER = 1 THEN 1 END) AS leader_count,
  COUNT(*) AS region_count
FROM INFORMATION_SCHEMA.TIKV_REGION_PEERS p
JOIN INFORMATION_SCHEMA.TIKV_STORE_STATUS s  ON p.STORE_ID = s.STORE_ID
GROUP BY s.STORE_ID, s.ADDRESS
ORDER BY s.STORE_ID limit 1000;
